package main

import (
	"errors"
	"fmt"
)

var ErrNotFound = errors.New("用户不存在")

type ValidationError struct{ Field string }

func (e *ValidationError) Error() string {
	return "字段 " + e.Field + " 不合法"
}

func findUser(id int) error {
	if id == 0 {
		return fmt.Errorf("查找用户 %d 失败: %w", id, ErrNotFound)
	}
	return nil
}

func validate(name string) error {
	if name == "" {
		return &ValidationError{Field: "name"}
	}
	return nil
}

func safe(fn func() error) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("panic 转成 error: %v", r)
		}
	}()
	return fn()
}

func main() {
	err := findUser(0)
	fmt.Println(err)
	fmt.Println(errors.Is(err, ErrNotFound))

	var ve *ValidationError
	if errors.As(validate(""), &ve) {
		fmt.Println("校验失败的字段:", ve.Field)
	}

	err = safe(func() error {
		panic("数据库连接炸了")
	})
	fmt.Println(err)
}
